enum Result {
    Success
    Failure = 2
    Unknown = 0x10
}

class Base {
}

class Log : Base, IDisposable {
    [string]$Path
    static [int]$Count = 0
    hidden $Cache
    [ValidateNotNull()][string]$Name

    Log([string]$path) {
        $this.Path = $path
    }

    [void] Write([string]$message, $level) {
        Add-Content -Path $this.Path -Value $message
    }

    static [Log] Create() {
        return [Log]::new('log.txt')
    }

    [void] Dispose() {
    }
}

